import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { type Page, expect, test } from "@playwright/test";

const here = fileURLToPath(new URL(".", import.meta.url));
const example = (name: string) => resolve(here, "../../examples", name);
// The SQLite sample is generated by scripts/build-site.sh, not checked in.
const generated = (name: string) => resolve(here, "../../site/examples", name);

/** Clicks `button`, which opens the browser's file chooser, and answers it with `files`. */
async function choose(page: Page, button: string, files: string[], exact = true) {
  const [chooser] = await Promise.all([
    page.waitForEvent("filechooser"),
    page.getByRole("button", { name: button, exact }).click(),
  ]);
  await chooser.setFiles(files);
}

/** The text of the first chart on the page (SVG text, as drawn). */
const firstChart = (page: Page) => page.locator(".vega-embed svg").first();

/** Picks a format in the Export menu, exports, and returns the downloaded file. */
async function exportAs(page: Page, format: string) {
  await page.locator("#export-format").selectOption(format);
  const [download] = await Promise.all([
    page.waitForEvent("download"),
    page.getByRole("button", { name: "Export..." }).click(),
  ]);
  return { name: download.suggestedFilename(), bytes: readFileSync(await download.path()) };
}

test.beforeEach(async ({ page }) => {
  await page.goto("/index.html");
  await expect(page.getByRole("heading", { name: "Welcome to Davilize" })).toBeVisible();
});

test("the sample report opens and draws its charts", async ({ page }) => {
  await page.getByRole("button", { name: "Try the sample report" }).click();
  await expect(page).toHaveTitle(/Sample sales - Davilize/);
  await expect(firstChart(page)).toContainText("West");
  await expect(page.getByRole("tab", { name: /Report \(4\)/ })).toBeVisible();
});

test("a report with a join opens and aggregates across it", async ({ page }) => {
  await choose(page, "Open report", [example("sample_joined.dvz"), example("sample.csv"), example("regions.csv")]);
  await expect(page).toHaveTitle(/Sample sales by manager - Davilize/);
  for (const manager of ["Ann", "Bo", "Cy", "Dee"]) await expect(firstChart(page)).toContainText(manager);
});

test("calculated fields from a report are listed", async ({ page }) => {
  await choose(page, "Open report", [example("sample_params.dvz"), example("sample.csv")]);
  await expect(page).toHaveTitle(/Sample sales \(parameters\) - Davilize/);
  const list = page.getByRole("list", { name: "Calculated fields of sales" });
  await expect(list).toContainText("net_revenue");
  await expect(list).toContainText("big_ticket");
});

test("a calculated field that reads files is refused", async ({ page }) => {
  await page.getByRole("button", { name: "Try the sample report" }).click();
  await expect(page).toHaveTitle(/Sample sales - Davilize/);
  await page.getByRole("button", { name: "Add calculated field" }).click();
  await page.locator("#calc-new-name").fill("evil");
  await page.locator("#calc-new-expression").fill("read_csv('/etc/passwd')");
  await expect(page.getByRole("alert").filter({ hasText: "not allowed" })).toBeVisible();
});

test("a SQLite database source is read in the browser", async ({ page }) => {
  await choose(page, "Open report", [example("sample_db.dvz"), generated("sample_db.sqlite")]);
  await expect(page).toHaveTitle(/Sample database - Davilize/);
  for (const product of ["Gadget", "Widget", "Gizmo"]) await expect(firstChart(page)).toContainText(product);
});

test("a database report without its database says which file to choose", async ({ page }) => {
  await choose(page, "Open report", [example("sample_db.dvz")]);
  await expect(page.getByText(/sample_db\.sqlite/).first()).toBeVisible();
});

test.describe("export", () => {
  test.beforeEach(async ({ page }) => {
    await page.getByRole("button", { name: "Try the sample report" }).click();
    await expect(page).toHaveTitle(/Sample sales - Davilize/);
  });

  test("HTML page", async ({ page }) => {
    const { name, bytes } = await exportAs(page, "html");
    expect(name).toMatch(/\.html$/);
    expect(bytes.toString("utf8")).toContain("vega");
  });

  test("Excel workbook, CSV zip, Power BI template and Tableau workbook", async ({ page }) => {
    const xlsx = await exportAs(page, "xlsx");
    expect(xlsx.name).toMatch(/\.xlsx$/);
    expect(xlsx.bytes.subarray(0, 2).toString()).toBe("PK");

    const csv = await exportAs(page, "csv");
    expect(csv.name).toMatch(/\.zip$/);
    expect(csv.bytes.subarray(0, 2).toString()).toBe("PK");

    const pbit = await exportAs(page, "pbit");
    expect(pbit.name).toMatch(/\.pbit$/);
    expect(pbit.bytes.includes("DataModelSchema")).toBe(true);

    const twb = await exportAs(page, "twb");
    expect(twb.name).toMatch(/\.twb$/);
    expect(twb.bytes.toString("utf8")).toContain("<workbook");
  });

  test("Power BI file with its data", async ({ page }) => {
    const pbix = await exportAs(page, "pbix");
    expect(pbix.name).toMatch(/\.pbix$/);
    expect(pbix.bytes.subarray(0, 2).toString()).toBe("PK");
    expect(pbix.bytes.includes("DataModel")).toBe(true);
    expect(pbix.bytes.length).toBeGreaterThan(5000);
  });
});

test("a Power BI template imports into a report", async ({ page }) => {
  await choose(page, "Open data files", [example("sample.csv"), example("regions.csv")], false);
  await expect(page.getByText("regions").first()).toBeVisible();
  await choose(page, "Import...", [example("sample_joined.pbit")]);
  await expect(page.getByText(/Imported to/)).toBeVisible();
  await expect(firstChart(page)).toBeVisible();
});

test("files and reports are kept across a reload", async ({ page }) => {
  await choose(page, "Open a report", [example("sample.dvz"), example("sample.csv")], false);
  await expect(page).toHaveTitle(/Sample sales - Davilize/);
  // Storing happens in the background; wait until both files are in the origin private file system.
  await expect
    .poll(() =>
      page.evaluate(async () => {
        const root = await navigator.storage.getDirectory();
        const dir = await root.getDirectoryHandle("davilize-files");
        let count = 0;
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        for await (const _ of (dir as any).entries()) count += 1;
        return count;
      }),
    )
    .toBe(2);

  await page.reload();
  await expect(page.getByRole("heading", { name: "Kept in this browser" })).toBeVisible();
  await page.getByRole("button", { name: "Open sample.dvz" }).click();
  await expect(page).toHaveTitle(/Sample sales - Davilize/);
  await expect(firstChart(page)).toContainText("West");

  await page.reload();
  await page.getByRole("button", { name: "Clear everything kept in this browser" }).click();
  await expect(page.getByRole("heading", { name: "Kept in this browser" })).toHaveCount(0);
});

test("the page makes no requests to other sites", async ({ page, baseURL }) => {
  const foreign: string[] = [];
  page.on("request", (request) => {
    const url = request.url();
    if (!url.startsWith(baseURL ?? "") && !/^(data|blob):/.test(url)) foreign.push(url);
  });
  await page.getByRole("button", { name: "Try the sample report" }).click();
  await expect(firstChart(page)).toContainText("West");
  expect(foreign).toEqual([]);
});

test("the app works offline after the first visit", async ({ page, context }) => {
  // The service worker stores the app (including the DuckDB engine) before it is "ready".
  await page.evaluate(async () => {
    await navigator.serviceWorker.ready;
  });
  await context.setOffline(true);
  await page.reload();
  await expect(page.getByRole("heading", { name: "Welcome to Davilize" })).toBeVisible();
  await page.getByRole("button", { name: "Try the sample report" }).click();
  await expect(page).toHaveTitle(/Sample sales - Davilize/);
  await expect(firstChart(page)).toContainText("West");
});
